import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { IconButtonProps } from "./icon-button.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

import { Button } from "../button";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "IconButton";

// Generate child element class names for the component, should match available style slots
export const IconButtonClasses = {
  root: "exp-textura_icon-button",
  sm: "exp-textura_icon-button_sm",
  secondary: "exp-textura_icon-button_secondary",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  destructive: {
    root: {
      backgroundColor: theme.buttonIcon.primary.destructive.color.background.enabled,
      color: theme.buttonIcon.primary.destructive.color.content.enabled,
      borderColor: theme.buttonIcon.primary.destructive.color.border.enabled,
    },
    hover: {
      backgroundColor: theme.buttonIcon.primary.destructive.color.background.hover,
      color: theme.buttonIcon.primary.destructive.color.content.hover,
      borderColor: theme.buttonIcon.primary.destructive.color.border.hover,
    },
    pressed: {
      backgroundColor: theme.buttonIcon.primary.destructive.color.background.pressed,
      color: theme.buttonIcon.primary.destructive.color.content.pressed,
      borderColor: theme.buttonIcon.primary.destructive.color.border.pressed,
    },
    selected: {
      backgroundColor: theme.buttonIcon.primary.destructive.color.background.selected,
      color: theme.buttonIcon.primary.destructive.color.content.selected,
      borderColor: theme.buttonIcon.primary.destructive.color.border.selected,
    },
    disabled: {
      backgroundColor: theme.buttonIcon.primary.destructive.color.background.disabled,
      color: theme.buttonIcon.primary.destructive.color.content.disabled,
      borderColor: theme.buttonIcon.primary.destructive.color.border.disabled,
    },
    secondary: {
      backgroundColor: theme.buttonIcon.secondary.destructive.color.background.enabled,
      color: theme.buttonIcon.secondary.destructive.color.content.enabled,
      borderColor: theme.buttonIcon.secondary.destructive.color.border.enabled,
    },
    secondaryHover: {
      backgroundColor: theme.buttonIcon.secondary.destructive.color.background.hover,
      color: theme.buttonIcon.secondary.destructive.color.content.hover,
      borderColor: theme.buttonIcon.secondary.destructive.color.border.hover,
    },
    secondaryPressed: {
      backgroundColor: theme.buttonIcon.secondary.destructive.color.background.pressed,
      color: theme.buttonIcon.secondary.destructive.color.content.pressed,
      borderColor: theme.buttonIcon.secondary.destructive.color.border.pressed,
    },
    secondarySelected: {
      backgroundColor: theme.buttonIcon.secondary.destructive.color.background.selected,
      color: theme.buttonIcon.secondary.destructive.color.content.selected,
      borderColor: theme.buttonIcon.secondary.destructive.color.border.selected,
    },
    secondaryDisabled: {
      backgroundColor: theme.buttonIcon.secondary.destructive.color.background.disabled,
      color: theme.buttonIcon.secondary.destructive.color.content.disabled,
      borderColor: theme.buttonIcon.secondary.destructive.color.border.disabled,
    },
  },
  inverse: {
    root: {
      backgroundColor: theme.buttonIcon.primary.inverse.color.background.enabled,
      color: theme.buttonIcon.primary.inverse.color.content.enabled,
      borderColor: theme.buttonIcon.primary.inverse.color.border.enabled,
    },
    hover: {
      backgroundColor: theme.buttonIcon.primary.inverse.color.background.hover,
      color: theme.buttonIcon.primary.inverse.color.content.hover,
      borderColor: theme.buttonIcon.primary.inverse.color.border.hover,
    },
    pressed: {
      backgroundColor: theme.buttonIcon.primary.inverse.color.background.pressed,
      color: theme.buttonIcon.primary.inverse.color.content.pressed,
      borderColor: theme.buttonIcon.primary.inverse.color.border.pressed,
    },
    selected: {
      backgroundColor: theme.buttonIcon.primary.inverse.color.background.selected,
      color: theme.buttonIcon.primary.inverse.color.content.selected,
      borderColor: theme.buttonIcon.primary.inverse.color.border.selected,
    },
    disabled: {
      backgroundColor: theme.buttonIcon.primary.inverse.color.background.disabled,
      color: theme.buttonIcon.primary.inverse.color.content.disabled,
      borderColor: theme.buttonIcon.primary.inverse.color.border.disabled,
    },
    secondary: {
      backgroundColor: theme.buttonIcon.secondary.inverse.color.background.enabled,
      color: theme.buttonIcon.secondary.inverse.color.content.enabled,
      borderColor: theme.buttonIcon.secondary.inverse.color.border.enabled,
    },
    secondaryHover: {
      backgroundColor: theme.buttonIcon.secondary.inverse.color.background.hover,
      color: theme.buttonIcon.secondary.inverse.color.content.hover,
      borderColor: theme.buttonIcon.secondary.inverse.color.border.hover,
    },
    secondaryPressed: {
      backgroundColor: theme.buttonIcon.secondary.inverse.color.background.pressed,
      color: theme.buttonIcon.secondary.inverse.color.content.pressed,
      borderColor: theme.buttonIcon.secondary.inverse.color.border.pressed,
    },
    secondarySelected: {
      color: theme.buttonIcon.secondary.inverse.color.content.selected,
      backgroundColor: theme.buttonIcon.secondary.inverse.color.background.selected,
      borderColor: theme.buttonIcon.secondary.inverse.color.border.selected,
    },
    secondaryDisabled: {
      backgroundColor: theme.buttonIcon.secondary.inverse.color.background.disabled,
      color: theme.buttonIcon.secondary.inverse.color.content.disabled,
      borderColor: theme.buttonIcon.secondary.inverse.color.border.disabled,
    },
  },
});

const generateStyles = (props: IconButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<IconButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    width: theme.toRem(32),
    height: theme.toRem(32),
    fontSize: theme.toRem(16),
    padding: 0,
    backgroundColor: theme.buttonIcon.primary.color.background.enabled,
    color: theme.buttonIcon.primary.color.content.enabled,
    border: `${theme.toRem(theme.buttonIcon.border.width)} solid ${theme.buttonIcon.primary.color.border.enabled}`,

    "&:hover": {
      backgroundColor: theme.buttonIcon.primary.color.background.hover,
      color: theme.buttonIcon.primary.color.content.hover,
      borderColor: theme.buttonIcon.primary.color.border.hover,
      ...styleSlots?.hover,
    },

    "&:active": {
      backgroundColor: theme.buttonIcon.primary.color.background.pressed,
      color: theme.buttonIcon.primary.color.content.pressed,
      borderColor: theme.buttonIcon.primary.color.border.pressed,
      ...styleSlots?.pressed,
    },

    "&[data-selected]": {
      backgroundColor: theme.buttonIcon.primary.color.background.selected,
      color: theme.buttonIcon.primary.color.content.selected,
      borderColor: theme.buttonIcon.primary.color.border.selected,
      ...styleSlots?.selected,
    },

    "&:disabled, &:disabled:hover": {
      cursor: "not-allowed",
      backgroundColor: theme.buttonIcon.primary.color.background.disabled,
      color: theme.buttonIcon.primary.color.content.disabled,
      borderColor: theme.buttonIcon.primary.color.border.disabled,
      ...styleSlots?.disabled,
    },

    "&:focus-visible": {
      ...theme.focusRing,
      ...styleSlots?.focus,
    },

    [`&.${IconButtonClasses.sm}`]: {
      fontSize: theme.toRem(14),
      width: theme.toRem(24),
      height: theme.toRem(24),
      ...styleSlots?.sm,
    },

    [`&.${IconButtonClasses.secondary}`]: {
      backgroundColor: theme.buttonIcon.secondary.color.background.enabled,
      color: theme.buttonIcon.secondary.color.content.enabled,
      borderColor: theme.buttonIcon.secondary.color.border.enabled,
      "&:hover": {
        backgroundColor: theme.buttonIcon.secondary.color.background.hover,
        color: theme.buttonIcon.secondary.color.content.hover,
        borderColor: theme.buttonIcon.secondary.color.border.hover,
        ...styleSlots?.secondaryHover,
      },
      "&:active": {
        backgroundColor: theme.buttonIcon.secondary.color.background.pressed,
        color: theme.buttonIcon.secondary.color.content.pressed,
        borderColor: theme.buttonIcon.secondary.color.border.pressed,
        ...styleSlots?.secondaryPressed,
      },
      "&[data-selected]": {
        backgroundColor: theme.buttonIcon.secondary.color.background.selected,
        color: theme.buttonIcon.secondary.color.content.selected,
        borderColor: theme.buttonIcon.secondary.color.border.selected,
        ...styleSlots?.secondarySelected,
      },
      "&:disabled, &:disabled:hover": {
        backgroundColor: theme.buttonIcon.secondary.color.background.disabled,
        color: theme.buttonIcon.secondary.color.content.disabled,
        borderColor: theme.buttonIcon.secondary.color.border.disabled,
        ...styleSlots?.secondaryDisabled,
      },
      ...styleSlots?.secondary,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledIconButton = styled(Button, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<IconButtonProps>((props) => generateStyles(props));
